window.FILM_WORK_PROMPTS={"work_id":"src-9ebfe241e112f5c0","records":[{"work_id":"src-9ebfe241e112f5c0","frame_id":"FG-3860438fecfd9bfd","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/imported_from_media_libray/thumb/angst007.jpg","source_page":"https://film-grab.com/2018/03/24/angst/","scene":"一座米黄色钟楼占据画面中心，塔身带有拱形百叶窗和罗马数字时钟。背景是阴沉的灰云天空，远处可见起伏的山丘、零散的房屋建筑以及左侧的圆顶结构。","analysis":"画面采用仰视视角，钟楼主体位于画面正中，占据约三分之二的垂直空间。塔身呈米黄色，带有白色装饰线条，上方是拱形百叶窗，下方是黑底白字的圆形时钟。背景天空布满厚重的灰色云层，光线平淡均匀，没有明显阴影。远处山丘呈暗褐色，与天空形成层次，整体色调偏冷且饱和度较低。","prompt":"低分辨率画面，仰视视角拍摄一座米黄色钟楼。塔身呈方形，带有白色装饰线条，上方是拱形百叶窗，下方是黑底白字的圆形时钟。背景是阴沉的灰云天空，远处可见起伏的山丘和零散的房屋建筑。左侧远处有一个圆顶结构。整体色调偏冷，光线平淡，没有明显阴影，呈现出一种阴郁的氛围。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-09T15:40:53-07:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/imported_from_media_libray/thumb/angst007.jpg","observed_dimensions":[500,288],"source_thumbnail_dimensions":[500,288],"source_image_match_mae":null,"observed_resolution":"low","observation_limits":["源画面最长边不足800像素，仅描述可辨的大轮廓、环境、构图和光色；细节待复核"],"id":"VP-37d9017df816b3b5","origin":"visual"},{"work_id":"src-9ebfe241e112f5c0","frame_id":"FG-1942c3a3bacbffc3","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/imported_from_media_libray/thumb/angst020.jpg","source_page":"https://film-grab.com/2018/03/24/angst/","scene":"昏暗室内，前景一位卷发人物坐在铺有红色床单的床沿，背景左侧一位穿深色西装的人物坐在轮椅上，右侧立有木质柜体。","analysis":"画面采用高角度俯视拍摄，构图呈现对角线分布。前景人物占据画面下方约三分之一，仅可见上半身及大腿，身体前倾，面部因角度和光线显得模糊。背景人物位于左后方，全身可见，坐姿端正。环境光线昏暗，整体色调偏冷，仅右侧柜体内部有暖色亮区，与大面积的暗色地面和家具形成对比。","prompt":"昏暗的室内场景，高角度俯视镜头。前景是一张铺着红色条纹床单的床，一位留着蓬松卷发的人物身穿深色上衣和格纹裤，坐在床沿，身体微微前倾，头部低垂。背景左侧，一位身穿深色西装的人物坐在轮椅上，面向右侧。房间地面铺设深蓝色地毯，左后方是深色木质衣柜，右后方有白色窗帘和暖气片。画面右侧边缘立着一个高大的木质展示柜，柜内格层透出暖黄色的灯光，是画面中主要的亮色来源。整体色调阴郁，光影对比强烈，呈现出一种压抑的视觉氛围。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-09T15:41:00-07:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/imported_from_media_libray/thumb/angst020.jpg","observed_dimensions":[500,288],"source_thumbnail_dimensions":[500,288],"source_image_match_mae":null,"observed_resolution":"low","observation_limits":["源画面最长边不足800像素，仅描述可辨的大轮廓、环境、构图和光色；细节待复核"],"id":"VP-08022484d33b2ac5","origin":"visual"},{"work_id":"src-9ebfe241e112f5c0","frame_id":"FG-ba2ddb6b3235ff82","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/imported_from_media_libray/thumb/angst033.jpg","source_page":"https://film-grab.com/2018/03/24/angst/","scene":"画面为一张极度贴近的人脸局部，背景全黑。人物面部占据绝大部分空间，一只眼睛正对镜头，另一只眼睛旁有一根银灰色细长物体斜向伸入。","analysis":"构图极度紧凑，仅可见人物面部上半部分，包括双眼、鼻梁、嘴唇及部分额头与发际。视角为平视或微仰，光线从上方或侧方打在面部，形成柔和的明暗过渡，皮肤呈现暖色调，背景为纯黑，对比强烈。银灰色物体从右下角斜向切入，指向人物眼部，增加了画面的紧张感。","prompt":"一张极度贴近的人脸局部特写，背景为纯黑。画面主体为一名浅色头发人物的面部，仅可见双眼、鼻梁、嘴唇及部分额头。人物皮肤白皙，嘴唇涂有橘红色口红，微微张开。一只眼睛正对镜头，眼神平静，另一只眼睛旁有一根银灰色的细长金属物体从右下角斜向伸入，尖端指向眼角。光线柔和地打在面部，形成细腻的明暗过渡，整体色调偏暖，与黑色背景形成强烈对比，营造出一种静谧而紧张的氛围。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-09T15:41:06-07:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/imported_from_media_libray/thumb/angst033.jpg","observed_dimensions":[500,288],"source_thumbnail_dimensions":[500,288],"source_image_match_mae":null,"observed_resolution":"low","observation_limits":["源画面最长边不足800像素，仅描述可辨的大轮廓、环境、构图和光色；细节待复核"],"id":"VP-2f3757a15f8fbe63","origin":"visual"},{"work_id":"src-9ebfe241e112f5c0","frame_id":"FG-95ea7683bdabe557","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/imported_from_media_libray/thumb/angst045.jpg","source_page":"https://film-grab.com/2018/03/24/angst/","scene":"一名穿深色上衣浅色裤子的人物在庭院中行走，前方是一栋带大面积玻璃窗的浅色建筑，左侧有茂密针叶林，前景有一棵无叶大树。","analysis":"画面采用高角度俯拍，前景无叶树干占据画面中央偏左，形成视觉遮挡。人物位于画面中下部，全身可见，体型在环境中显得较小。建筑位于右侧，玻璃窗反射出冷调光线。左侧针叶林颜色深沉，与右侧浅色建筑形成明暗对比。整体光线均匀偏冷，地面呈现灰白色调，带有阴影。","prompt":"高角度俯拍视角，画面中央偏左有一棵无叶大树，树干分叉，枝条向四周伸展。树下庭院中，一名穿深色上衣和浅色长裤的人物正背对镜头向右侧建筑行走。右侧是一栋浅色外墙建筑，底层有大面积玻璃窗，窗内透出冷白光，屋顶呈深褐色。左侧是茂密的深绿色针叶林，地面为灰白色碎石或水泥地，散落着枯叶和阴影。整体色调偏冷，光线柔和均匀，呈现出清冷的氛围。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-09T15:41:12-07:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/imported_from_media_libray/thumb/angst045.jpg","observed_dimensions":[500,288],"source_thumbnail_dimensions":[500,288],"source_image_match_mae":null,"observed_resolution":"low","observation_limits":["源画面最长边不足800像素，仅描述可辨的大轮廓、环境、构图和光色；细节待复核"],"id":"VP-579508b95914c643","origin":"visual"},{"work_id":"src-9ebfe241e112f5c0","frame_id":"FG-324cc70090a272ae","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/imported_from_media_libray/thumb/angst058.jpg","source_page":"https://film-grab.com/2018/03/24/angst/","scene":"昏暗混凝土走廊内，前景左下角有一人倒地，中景处另一人坐靠墙边，尽头出口处停着一辆白色车辆，右侧立有圆柱形罐体。","analysis":"画面采用一点透视构图，视线沿走廊延伸至尽头。前景人物仅可见躯干与腿部轮廓，呈倒地姿态，周围地面有大片暗红色色块；中景人物呈坐姿，身形较小，位于左侧墙根。右侧巨大的圆柱形罐体占据显著空间，增强了纵深感。整体光线昏暗，色调偏冷灰，尽头出口处有自然亮光，与内部阴影形成强烈明暗对比。","prompt":"昏暗的混凝土走廊内部，低分辨率画面。前景左下角有一人倒地，身体轮廓模糊，周围地面分布着大片暗红色不规则色块。中景左侧墙根处，另一人呈坐姿，身形较小，衣着颜色深暗。右侧矗立着一个巨大的圆柱形金属罐体，表面有斑驳痕迹。走廊尽头是明亮的出口，停着一辆白色车辆，车尾朝向镜头。整体色调阴冷，以灰绿色和暗灰色为主，光线从远处入口射入，形成强烈的明暗对比，营造出压抑、静谧的视觉氛围。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-09T15:41:19-07:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/imported_from_media_libray/thumb/angst058.jpg","observed_dimensions":[500,288],"source_thumbnail_dimensions":[500,288],"source_image_match_mae":null,"observed_resolution":"low","observation_limits":["源画面最长边不足800像素，仅描述可辨的大轮廓、环境、构图和光色；细节待复核"],"id":"VP-d3f74ca2ad76051c","origin":"visual"},{"work_id":"src-9ebfe241e112f5c0","frame_id":"FG-4995541950da5372","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/imported_from_media_libray/thumb/angst006.jpg","source_page":"https://film-grab.com/2018/03/24/angst/","scene":"两名背对镜头的人物行走在狭长的高顶走廊中，左侧人物穿深色上衣，右侧人物着黑色制服并戴帽，两侧墙壁排列着门，尽头有亮光。","analysis":"采用中心对称构图，利用两侧墙壁和顶部钢架结构形成强烈的透视引导线，将视线汇聚于画面深处。人物位于画面中下部，呈现全身至大腿可见范围，右侧人物因身形或位置显得略大。整体色调偏冷，以青灰色和黑色为主，顶部中央的矩形亮区与尽头的窗户形成明暗对比，营造出幽深、压抑的空间氛围。","prompt":"低分辨率画面，两名背对镜头的人物正行走在一条狭长、高耸的工业风走廊中。左侧人物身穿深灰色长袖上衣和深色长裤，右侧人物身着黑色西装式制服，头戴黑色大檐帽。走廊两侧是灰白色的墙壁，排列着深色的门，顶部有复杂的金属桁架结构支撑。画面尽头是一扇透着冷白光的窗户，顶部中央也有一个明亮的矩形光源。整体色调阴冷，以青灰色和黑色为主，利用两侧墙壁形成的强烈透视感将视线引向深处，营造出一种压抑、肃穆的视觉感受。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-14T18:08:20+08:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/imported_from_media_libray/thumb/angst006.jpg","observed_dimensions":[500,288],"source_thumbnail_dimensions":[500,288],"source_image_match_mae":null,"observed_resolution":"low","observation_limits":["源画面最长边不足800像素，仅描述可辨的大轮廓、环境、构图和光色；细节待复核"],"id":"VP-f89f1f8218be58f8","origin":"visual"},{"work_id":"src-9ebfe241e112f5c0","frame_id":"FG-2c6f608d9a2076e8","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/imported_from_media_libray/thumb/angst019.jpg","source_page":"https://film-grab.com/2018/03/24/angst/","scene":"昏暗室内，一名身穿深色外套与浅色长裤的人物站立在右侧墙边，左侧可见一扇挂着花纹门帘的门洞，整体环境幽暗。","analysis":"画面采用左虚右实的布局，左侧门洞占据约三分之一宽度，右侧人物占据主要视觉重心。人物全身可见，呈站立姿态，头部微仰。环境光线极弱，呈现冷蓝色调，人物面部及身体大部分处于阴影中，仅衣物轮廓依稀可辨，明暗对比强烈，细节模糊。","prompt":"低分辨率昏暗室内画面，冷蓝色调。画面左侧是一扇敞开的门，挂着带有圆形花纹的浅色门帘，门内透出微弱亮光。画面右侧站立着一名人物，身穿深色西装外套，内搭浅色衬衫，下着浅色长裤。人物全身可见，姿态放松，头部略微后仰，面部隐没在阴影中。背景为深色墙壁，整体光影对比强烈，大部分区域处于黑暗中，仅保留人物轮廓与门帘的可见细节。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-14T18:08:26+08:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/imported_from_media_libray/thumb/angst019.jpg","observed_dimensions":[500,288],"source_thumbnail_dimensions":[500,288],"source_image_match_mae":null,"observed_resolution":"low","observation_limits":["源画面最长边不足800像素，仅描述可辨的大轮廓、环境、构图和光色；细节待复核"],"id":"VP-7531a0fe6f545a87","origin":"visual"},{"work_id":"src-9ebfe241e112f5c0","frame_id":"FG-a4dcff84a1d80d1e","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/imported_from_media_libray/thumb/angst032.jpg","source_page":"https://film-grab.com/2018/03/24/angst/","scene":"仰视视角下的人物面部局部，头部后仰，嘴部张开，背景为模糊的冷色调暗区，画面主体占据绝大部分空间。","analysis":"构图极度紧凑，仅呈现人物面部下半部分及鼻部，头部向后仰起，下巴朝向画面上方。光线从上方投射，照亮面部皮肤与张开的嘴部，背景呈现深蓝色调的模糊色块，明暗对比强烈，色彩以肤色与冷色背景为主。","prompt":"低分辨率仰视视角画面，人物头部极度后仰，面部占据画面主体，仅可见鼻部、张开的嘴部及下巴轮廓。嘴唇涂有深红色，嘴部张开露出深色口腔内部。面部皮肤在上方光源照射下呈现苍白色调，带有细微纹理。背景为模糊的深蓝色冷调色块，与前景暖色皮肤形成对比。画面焦点集中在面部下半部分，整体氛围压抑，光影层次分明，无其他可见物体或人物。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-14T18:08:31+08:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/imported_from_media_libray/thumb/angst032.jpg","observed_dimensions":[500,288],"source_thumbnail_dimensions":[500,288],"source_image_match_mae":null,"observed_resolution":"low","observation_limits":["源画面最长边不足800像素，仅描述可辨的大轮廓、环境、构图和光色；细节待复核"],"id":"VP-5661b6317ccb2704","origin":"visual"},{"work_id":"src-9ebfe241e112f5c0","frame_id":"FG-ed6867f0c603c908","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/imported_from_media_libray/thumb/angst046.jpg","source_page":"https://film-grab.com/2018/03/24/angst/","scene":"一名身穿深色外套与浅色长裤的人物站在破碎的玻璃门外，身体前倾，门内地面散落着大量玻璃碎片，左侧可见室内墙壁与红色容器。","analysis":"画面采用室内向外看的视角，前景门框形成框架式构图。人物全身可见，位于画面中景，身体略微前倾，姿态紧张。室内光线较暗，室外光线明亮，形成明暗对比。地面玻璃碎片反射出高光，增强了画面的破碎感。","prompt":"低分辨率画面，室内视角透过破碎的玻璃门向外看。前景是米色门框，地面散落着大量反光的玻璃碎片。门外站着一名全身可见的人物，身穿深色外套和浅色长裤，身体前倾，姿态紧张。左侧室内墙壁上挂着一个红色容器。室外背景是模糊的庭院和树木，光线明亮，与室内形成明暗对比。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-14T18:08:36+08:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/imported_from_media_libray/thumb/angst046.jpg","observed_dimensions":[500,288],"source_thumbnail_dimensions":[500,288],"source_image_match_mae":null,"observed_resolution":"low","observation_limits":["源画面最长边不足800像素，仅描述可辨的大轮廓、环境、构图和光色；细节待复核"],"id":"VP-9b29549843dc71c3","origin":"visual"},{"work_id":"src-9ebfe241e112f5c0","frame_id":"FG-bb5a806bd0f76895","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/imported_from_media_libray/thumb/angst059.jpg","source_page":"https://film-grab.com/2018/03/24/angst/","scene":"一只戴着黑色手套的手在左侧捏住一张矩形照片，照片内是一名卷发女性的上半身肖像。背景为大面积的黑色模糊结构，右侧可见金属边缘。","analysis":"构图以手持照片为视觉中心，照片占据画面左侧约三分之一区域。照片内人物仅显示头部及肩部，背景为浅灰色斑驳墙面。外部背景极暗，右侧有模糊的黑色弧形物体及金属反光。光线集中在照片表面，使照片内容清晰，与周围黑暗环境形成强烈明暗对比。","prompt":"低分辨率画面，左侧一只戴黑色手套的手捏住一张矩形照片。照片内是一名棕色卷发女性的上半身肖像，她穿着黄色上衣，背景为浅灰色斑驳墙面。照片外部是昏暗的黑色环境，右侧可见模糊的黑色弧形结构及金属边缘。光线集中在照片上，使其在黑暗背景中显得明亮，整体色调偏冷，具有明显的颗粒感。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-14T18:08:42+08:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/imported_from_media_libray/thumb/angst059.jpg","observed_dimensions":[500,288],"source_thumbnail_dimensions":[500,288],"source_image_match_mae":null,"observed_resolution":"low","observation_limits":["源画面最长边不足800像素，仅描述可辨的大轮廓、环境、构图和光色；细节待复核"],"id":"VP-8c55c13489219346","origin":"visual"}]};